// Title: Render an Aspose.Cells column chart to a temporary PNG file and automatically delete it in C#
// Common Searches: how to render an Aspose.Cells chart to a temporary PNG file in C# | C# delete temporary image file after exporting an Aspose.Cells chart | schedule cleanup of a temp PNG generated by Aspose.Cells chart rendering | using Chart.ToImage with a unique temp path in .NET | best practice for temporary file handling when saving Aspose.Cells chart images
// Tags: Aspose.Cells chart to PNG export | C# temporary file creation and cleanup | Chart.ToImage method usage | unique temp file path generation .NET | automatic deletion of temp files

using System;
using System.IO;
using Aspose.Cells;
using Aspose.Cells.Charts;
using Aspose.Cells.Drawing;
using Aspose.Cells.Rendering;

namespace AsposeCellsChartToTempPng
{
    // The example creates a workbook, adds sample data and a column chart, then renders the chart to a uniquely named temporary PNG file using Chart.ToImage. It displays the file path and size, waits for user input, and finally deletes the temporary file immediately or registers a ProcessExit handler to ensure cleanup if deletion fails.
    class Program
    {
        static void Main(string[] args)
        {
            // Path of the temporary PNG file (unique name, .png extension)
            string tempPngPath = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString() + ".png");

            // Flag to know whether the file was created successfully
            bool fileCreated = false;

            try
            {
                // ------------------------------------------------------------
                // 1. Create a workbook and populate it with sample data
                // ------------------------------------------------------------
                Workbook workbook = new Workbook();
                Worksheet sheet = workbook.Worksheets[0];

                // Sample data for the chart
                sheet.Cells["A1"].PutValue("Category");
                sheet.Cells["A2"].PutValue("Apple");
                sheet.Cells["A3"].PutValue("Orange");
                sheet.Cells["A4"].PutValue("Banana");

                sheet.Cells["B1"].PutValue("Sales");
                sheet.Cells["B2"].PutValue(1200);
                sheet.Cells["B3"].PutValue(800);
                sheet.Cells["B4"].PutValue(1500);

                // ------------------------------------------------------------
                // 2. Add a column chart and bind it to the data range
                // ------------------------------------------------------------
                int chartIndex = sheet.Charts.Add(ChartType.Column, 5, 0, 20, 8);
                Chart chart = sheet.Charts[chartIndex];
                chart.NSeries.Add("B2:B4", true);
                chart.NSeries.CategoryData = "A2:A4";

                // ------------------------------------------------------------
                // 3. Render the chart to a PNG file in the temporary location
                // ------------------------------------------------------------
                // Using the overload that accepts a file name and ImageType
                chart.ToImage(tempPngPath, ImageType.Png);
                fileCreated = true;

                Console.WriteLine($"Chart image successfully written to temporary file:");
                Console.WriteLine($"  {tempPngPath}");

                // ------------------------------------------------------------
                // 4. (Optional) Do something with the PNG file – e.g., read its size
                // ------------------------------------------------------------
                FileInfo info = new FileInfo(tempPngPath);
                Console.WriteLine($"Temporary PNG file size: {info.Length} bytes");

                // Here you could load the image, send it over a network, etc.
                // For demonstration we just pause so you can inspect the file if needed.
                Console.WriteLine("Press any key to continue and delete the temporary file...");
                Console.ReadKey();
            }
            catch (Exception ex)
            {
                Console.Error.WriteLine("An error occurred while creating the chart image:");
                Console.Error.WriteLine(ex.Message);
            }
            finally
            {
                // ------------------------------------------------------------
                // 5. Ensure the temporary file is deleted regardless of success/failure
                // ------------------------------------------------------------
                if (fileCreated && File.Exists(tempPngPath))
                {
                    try
                    {
                        File.Delete(tempPngPath);
                        Console.WriteLine($"Temporary file deleted: {tempPngPath}");
                    }
                    catch (Exception delEx)
                    {
                        // If deletion fails, schedule deletion on process exit as a fallback
                        Console.Error.WriteLine($"Failed to delete temporary file immediately: {delEx.Message}");
                        AppDomain.CurrentDomain.ProcessExit += (s, e) =>
                        {
                            try
                            {
                                if (File.Exists(tempPngPath))
                                    File.Delete(tempPngPath);
                            }
                            catch { /* swallow any finalizer errors */ }
                        };
                    }
                }
            }
        }
    }
}
